create table if not exists public.letter_heads (id uuid primary key default gen_random_uuid(), subject text not null, letter_date date not null default current_date, content text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.letter_heads enable row level security; create policy "Authenticated users can view letters" on public.letter_heads for select to authenticated using (true); create policy "Authenticated users can insert letters" on public.letter_heads for insert to authenticated with check (true); create policy "Authenticated users can update letters" on public.letter_heads for update to authenticated using (true) with check (true); create policy "Authenticated users can delete letters" on public.letter_heads for delete to authenticated using (true);